describe('File Download Functionality', () => {
    const fileName = 'uploadedFile.txt';
    const downloadUrl = '/downloads/' + fileName;

    beforeEach(() => {
        cy.visit('/file-upload-page');
    });

    it('should successfully download the previously uploaded file', () => {
        cy.intercept('GET', downloadUrl).as('downloadFile');
        cy.get('button#download-file').click();
        cy.wait('@downloadFile').its('response.statusCode').should('eq', 200);
        cy.readFile(`cypress/downloads/${fileName}`).should('exist');
    });

    it('should handle file not found error gracefully', () => {
        cy.intercept('GET', downloadUrl, { statusCode: 404 }).as('downloadFileNotFound');
        cy.get('button#download-file').click();
        cy.wait('@downloadFileNotFound');
        cy.get('.error-message').should('contain', 'File not found');
    });
});
